local byId, byName
local function Index()
  if byId then return end
  byId, byName = {}, {}
  for _, e in ipairs(NS.FishingCatchCatalog) do
    byId[e.itemId] = e
    byName[e.name] = e
  end
end

function NS.FishingCatalogById()
  Index()
  return byId
end

function NS.FishingCatalogByName()
  Index()
  return byName
end
